package configuration

import (
	"strconv"
)

// Source resolves a configuration key to a raw value.
type Source func(key string) (value string, found bool)

// Config holds the loaded application configuration.
type Config struct {
	Port  int
	Name  string
	Debug bool
}

// Load reads configuration keys from source and returns a parsed Config.
func Load(source Source) (Config, error) {
	cfg := Config{
		Port:  8080,
		Name:  "helios",
		Debug: false,
	}

	if v, ok := source("HELIOS_PORT"); ok {
		p, err := strconv.Atoi(v)
		if err != nil {
			return Config{}, strconv.NumError{Func: "Atoi", Num: v, Err: err}
		}
		if p < 1 || p > 65535 {
			return Config{}, &strconv.NumError{
				Func: "Atoi",
				Num:  v,
				Err:  strconv.ErrRange,
			}
		}
		cfg.Port = p
	}

	if v, ok := source("HELIOS_NAME"); ok {
		if v == "" {
			return Config{}, &emptyNameError{}
		}
		cfg.Name = v
	}

	if v, ok := source("HELIOS_DEBUG"); ok {
		d, err := strconv.ParseBool(v)
		if err != nil {
			return Config{}, err
		}
		cfg.Debug = d
	}

	return cfg, nil
}

// emptyNameError is returned when HELIOS_NAME is present but empty.
type emptyNameError struct{}

func (e *emptyNameError) Error() string {
	return "HELIOS_NAME must not be empty"
}

package main

import (
	"fmt"
	"os"

	"example.helios/configuration"
)

func main() {
	cfg, err := configuration.Load(configuration.Source(os.LookupEnv))
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Printf("port=%d name=%s debug=%t\n", cfg.Port, cfg.Name, cfg.Debug)
}

package configuration

import (
	"errors"
	"strconv"
	"testing"
)

func mapSource(m map[string]string) Source {
	return func(key string) (string, bool) {
		v, ok := m[key]
		return v, ok
	}
}

func TestDefaults(t *testing.T) {
	cfg, err := Load(mapSource(nil))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want helios", cfg.Name)
	}
	if cfg.Debug {
		t.Errorf("Debug = true, want false")
	}
}

func TestDefaultsEmptyMap(t *testing.T) {
	cfg, err := Load(mapSource(map[string]string{}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want helios", cfg.Name)
	}
	if cfg.Debug {
		t.Errorf("Debug = true, want false")
	}
}

func TestCustomPort(t *testing.T) {
	cfg, err := Load(mapSource(map[string]string{
		"HELIOS_PORT": "9090",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 9090 {
		t.Errorf("Port = %d, want 9090", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want helios", cfg.Name)
	}
}

func TestCustomName(t *testing.T) {
	cfg, err := Load(mapSource(map[string]string{
		"HELIOS_NAME": "myapp",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Name != "myapp" {
		t.Errorf("Name = %q, want myapp", cfg.Name)
	}
}

func TestCustomDebugTrue(t *testing.T) {
	cfg, err := Load(mapSource(map[string]string{
		"HELIOS_DEBUG": "true",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !cfg.Debug {
		t.Errorf("Debug = false, want true")
	}
}

func TestCustomDebugOne(t *testing.T) {
	cfg, err := Load(mapSource(map[string]string{
		"HELIOS_DEBUG": "1",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !cfg.Debug {
		t.Errorf("Debug = false, want true")
	}
}

func TestAllCustom(t *testing.T) {
	cfg, err := Load(mapSource(map[string]string{
		"HELIOS_PORT":  "443",
		"HELIOS_NAME":  "production",
		"HELIOS_DEBUG": "false",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 443 {
		t.Errorf("Port = %d, want 443", cfg.Port)
	}
	if cfg.Name != "production" {
		t.Errorf("Name = %q, want production", cfg.Name)
	}
	if cfg.Debug {
		t.Errorf("Debug = true, want false")
	}
}

func TestPortParseError(t *testing.T) {
	_, err := Load(mapSource(map[string]string{
		"HELIOS_PORT": "notanumber",
	}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	var numErr *strconv.NumError
	if !errors.As(err, &numErr) {
		t.Errorf("error type = %T, want *strconv.NumError", err)
	}
}

func TestPortOutOfRangeLow(t *testing.T) {
	_, err := Load(mapSource(map[string]string{
		"HELIOS_PORT": "0",
	}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	var numErr *strconv.NumError
	if !errors.As(err, &numErr) {
		t.Errorf("error type = %T, want *strconv.NumError", err)
	}
}

func TestPortOutOfRangeHigh(t *testing.T) {
	_, err := Load(mapSource(map[string]string{
		"HELIOS_PORT": "65536",
	}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	var numErr *strconv.NumError
	if !errors.As(err, &numErr) {
		t.Errorf("error type = %T, want *strconv.NumError", err)
	}
}

func TestEmptyName(t *testing.T) {
	_, err := Load(mapSource(map[string]string{
		"HELIOS_NAME": "",
	}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
}

func TestBadDebug(t *testing.T) {
	_, err := Load(mapSource(map[string]string{
		"HELIOS_DEBUG": "maybe",
	}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
}

